// The parts of Laravel that sit on top of the encrypter, produced by the real Laravel classes
// (fixtures/app-vectors.json, regenerated by scripts/generate_app_vectors.php): random keys,
// encrypted cookies, encrypted session payloads and Eloquent encrypted casts. Previous keys are
// covered here too, since cookies and rotated payloads depend on them.
const crypto = require('crypto');
const { LaravelEncrypter } = require('../src/index');
const { ALL_CIPHERS, keySize, rawKey, newEnc, edit, flipFirst, fixtures, fixtureEncrypter } = require('./helpers');

const app = require('../fixtures/app-vectors.json');
const fx = fixtures();
const b64 = (s) => Buffer.from(s, 'base64');

const appKey = (cipher, field = 'key_b64') => b64(app[field]).subarray(0, keySize(cipher));
const appEnc = (cipher, withPrevious = false) => {
    const enc = new LaravelEncrypter(appKey(cipher), cipher);
    return withPrevious ? enc.previousKeys([appKey(cipher, 'previous_key_b64')]) : enc;
};

describe('random keys', () => {
    test('every cipher works with keys Laravel generated', () => {
        expect(app.random_keys.length).toBeGreaterThanOrEqual(96);
        for (const v of app.random_keys) {
            const enc = new LaravelEncrypter(b64(v.key_b64), v.cipher);
            expect(enc.decryptString(v.payload)).toBe(b64(v.plaintext_b64).toString());
        }
    });
});

describe('cookies', () => {
    test.each(app.cookies.map((v) => [v.name, v]))('%s decrypts and validates', (_name, v) => {
        const want = b64(v.value_b64).toString();
        const current = appEnc(v.cipher);
        const rotated = appEnc(v.cipher, true);
        if (v.key === 'current') {
            expect(current.decryptCookie(v.cookie_name, v.payload)).toBe(want);
            expect(rotated.decryptCookie(v.cookie_name, v.payload)).toBe(want);
        } else {
            // Issued before the key was rotated: only an encrypter that knows the old key can read
            // it, because the prefix is bound to the key it was issued with.
            expect(() => current.decryptCookie(v.cookie_name, v.payload)).toThrow();
            expect(rotated.decryptCookie(v.cookie_name, v.payload)).toBe(want);
        }
    });

    test('a cookie is bound to its name', () => {
        const v = app.cookies.find((c) => c.cookie_name === 'laravel_session' && c.key === 'current');
        const enc = appEnc(v.cipher);
        expect(enc.decryptCookie('laravel_session', v.payload)).toBeTruthy();
        expect(() => enc.decryptCookie('XSRF-TOKEN', v.payload)).toThrow('The cookie value prefix is invalid.');
        // a payload from encryptString has no prefix at all, and a short one cannot hold it
        for (const plain of ['no prefix here, but long enough to hold one: 0123456789', 'short']) {
            expect(() => enc.decryptCookie('laravel_session', enc.encryptString(plain))).toThrow('The cookie value prefix is invalid.');
        }
        expect(() => enc.decryptCookie('laravel_session', 'garbage')).toThrow(/The payload is invalid/);
    });

    test.each(ALL_CIPHERS)('%s: cookies round-trip with Laravel\'s layout', (cipher) => {
        const enc = newEnc(cipher);
        for (const [name, value] of [['laravel_session', 'abc123'], ['empty', ''], ['pipes', 'a|b|c'], ['küche', 'Grüße 世界']]) {
            const payload = enc.encryptCookie(name, value);
            expect(enc.decryptCookie(name, payload)).toBe(value);

            // the plaintext is a 41-byte prefix (40 lower-case hex characters and "|") plus the value
            const plain = Buffer.from(enc.decryptString(payload));
            expect(plain.length).toBe(41 + Buffer.byteLength(value));
            expect(plain.subarray(0, 40).toString()).toMatch(/^[0-9a-f]{40}$/);
            expect(plain[40]).toBe(0x7c);
            expect(plain.subarray(41).toString()).toBe(value);
        }
    });

    test('the prefix matches Laravel\'s', () => {
        // PHP: hash_hmac('sha1', 'laravel_session' . 'v2', str_repeat("\x2b", 32)) . '|'
        const enc = newEnc('aes-256-cbc');
        expect(enc.decryptString(enc.encryptCookie('laravel_session', 'x')))
            .toBe('de34b8b683dec375f8d5c86fc41645c59842c10e|x');
    });
});

describe('Eloquent encrypted casts', () => {
    test('payloads decrypt to the value or its JSON', () => {
        expect(app.casts.length).toBeGreaterThanOrEqual(16);
        for (const v of app.casts) {
            // a cast is Crypt::encryptString() of the value, or of its JSON
            expect(appEnc(v.cipher).decryptString(v.payload)).toBe(b64(v.plaintext_b64).toString());
        }
    });

    test('the JSON casts hold JSON', () => {
        const v = app.casts.find((c) => c.name === 'aes-256-cbc/list');
        expect(JSON.parse(appEnc(v.cipher).decryptString(v.payload))).toEqual({ x: 1, y: [1, 2], z: 'ü' });
    });
});

describe('encrypted sessions', () => {
    test.each(app.sessions.map((v) => [v.name, v]))('%s', (_name, v) => {
        const enc = appEnc(v.cipher);

        // session.encrypt stores Crypt::encrypt() of the already serialized attributes, so the
        // value Laravel decrypts to is a string holding the PHP (or JSON) serialization
        const inner = enc.decrypt(v.payload);
        expect(typeof inner).toBe('string');
        expect(Buffer.from(inner)).toEqual(b64(v.inner_b64));

        if (v.serialization === 'php') {
            const attributes = enc.unserialize(inner);
            expect(attributes).toMatchObject({ user_id: 7, name: 'Grüße', cart: { apple: 2, pear: 1 }, _token: v.token });
            // ...and writes back what Laravel reads
            expect(enc.unserialize(enc.serialize(attributes))).toEqual(attributes);
            expect(enc.decrypt(enc.encrypt(enc.serialize(attributes)))).toBe(enc.serialize(attributes));
        } else {
            expect(JSON.parse(inner)).toMatchObject({ user_id: 7, _token: v.token });
        }
    });

    test('both serializations are covered', () => {
        expect(new Set(app.sessions.map((v) => v.serialization))).toContain('php');
    });
});

describe('previous keys', () => {
    test('rotated payloads from Laravel decrypt with the previous key', () => {
        expect(fx.rotated.length).toBeGreaterThanOrEqual(4);
        for (const v of fx.rotated) {
            const size = keySize(v.cipher);
            const current = fixtureEncrypter(fx, v.cipher);
            expect(() => current.decryptString(v.payload)).toThrow();
            const previous = b64(fx.previous_key_b64).subarray(0, size);
            const rotated = new LaravelEncrypter(b64(fx.key_b64).subarray(0, size), v.cipher, 'php', { previousKeys: [previous] });
            expect(rotated.decryptString(v.payload)).toBe(b64(v.plaintext_b64).toString());
        }
    });

    describe.each(ALL_CIPHERS)('%s', (cipher) => {
        const old = newEnc(cipher, 0x01);
        const older = newEnc(cipher, 0x02);
        const currentOnly = newEnc(cipher, 0x03);
        const rotated = newEnc(cipher, 0x03).previousKeys([rawKey(cipher, 0x01), `base64:${rawKey(cipher, 0x02).toString('base64')}`]);

        test('old payloads decrypt, new ones use the current key', () => {
            for (const legacy of [old, older]) {
                const payload = legacy.encryptString('legacy');
                expect(() => currentOnly.decryptString(payload)).toThrow();
                expect(rotated.decryptString(payload)).toBe('legacy');
            }
            const fresh = rotated.encryptString('fresh');
            expect(currentOnly.decryptString(fresh)).toBe('fresh');
            expect(() => old.decryptString(fresh)).toThrow();
        });

        test('unrelated keys and tampering are still rejected', () => {
            expect(() => rotated.decryptString(newEnc(cipher, 0x09).encryptString('x'))).toThrow();
            const bad = edit(old.encryptString('legacy'), (p) => { p.value = flipFirst(p.value); });
            expect(() => rotated.decryptString(bad)).toThrow();
        });
    });

    test('keys must fit the cipher and are chainable', () => {
        const enc = newEnc('aes-256-cbc');
        expect(() => enc.previousKeys([Buffer.alloc(16)])).toThrow(/Invalid key length/);
        expect(() => new LaravelEncrypter(rawKey('aes-256-cbc'), 'aes-256-cbc', 'php', { previousKeys: [Buffer.alloc(5)] })).toThrow(/Invalid key length/);
        expect(enc.previousKeys([])).toBe(enc);
        const keys = [crypto.randomBytes(32)];
        enc.previousKeys(keys);
        expect(enc.getPreviousKeys()).toEqual(keys);
        expect(enc.getAllKeys()).toEqual([enc.getKey(), ...keys]);
    });
});

describe('base64: key parsing like EncryptionServiceProvider', () => {
    test('padding is optional and stray characters are skipped', () => {
        const key = Buffer.alloc(32, 0xfb);
        const padded = key.toString('base64');
        expect(padded.endsWith('=')).toBe(true);
        expect(new LaravelEncrypter(`base64:${padded.replace(/=+$/, '')}`).getKey()).toEqual(key);
        expect(new LaravelEncrypter(`base64:${padded}\n`).getKey()).toEqual(key);
    });

    test('a malformed value decodes to the wrong length and is rejected', () => {
        // PHP: bin2hex(base64_decode("!!!not base64!!!")) === "9e8b5b6ac7ba"
        expect(() => new LaravelEncrypter('base64:!!!not base64!!!')).toThrow(/Expected 32 bytes, got 6 bytes/);
    });
});
